چاپ("تست بشکن و ادامه:");
عدد شماره = 0;
تاوقتی (true) {
    شماره = شماره + 1;
    اگر (شماره == 2) {
        ادامه; // رد شدن از عدد ۲
    }
    چاپ("  شماره " + شماره);
    اگر (شماره == 4) {
        بشکن;    // توقف در ۴
    }
}

value.en:
print("Testing break and continue:");
int currentNum = 0;
while (true) {
    currentNum = currentNum + 1;
    if (currentNum == 2) {
        continue; // Skip number 2
    }
    print("  Number " + currentNum);
    if (currentNum == 4) {
        break;    // Stop at 4
    }
}

