整数 番号 = 0;
の間 (true) {
    番号 = 番号 + 1;
    もし (番号 == 2) {
        続行; // 番号 2 をスキップ
    }
    表示("  番号 " + 番号);
    もし (番号 == 4) {
        中断;    // 4 で停止
    }
}

