печать("Тест прервать и продолжить:");
цел номер = 0;
пока (true) {
    номер = номер + 1;
    если (номер == 2) {
        продолжить; // Пропуск числа 2
    }
    печать("  Номер " + номер);
    если (номер == 4) {
        прервать;    // Остановка на 4
    }
}
